/*
Realistic Diamond Shader by ChatGPT with Zoom Effect
-------------------------------------------------------
This shader ray marches a convex “diamond” defined by 17 planes:
  • A horizontal “table” facet (at y=T)
  • 8 “crown” facets (joining the table edge to the girdle)
  • 8 “pavilion” facets (joining the girdle to the culet)
It uses iChannel0 as a cubemap for reflections/refractions and
computes a slight chromatic dispersion in the refracted rays.
The camera slowly circles the diamond while also zooming in and out.
*/

#ifdef GL_ES
precision mediump float;
#endif

#define MAX_STEPS 128
#define MAX_DIST 10.0
#define EPSILON 0.001
#define PI 3.14159265359

// ------------------------------------------------------------------
// Diamond parameters (feel free to adjust these to change the cut):
const float T  = 0.8;   // table height (y coordinate)
const float R  = 0.3;   // table radius (edge of table)
const float R2 = 0.4;   // girdle radius (widest part)
const float P  = 1.2;   // culet depth (pavilion tip at y = -P)

// ------------------------------------------------------------------
// Compute the signed distance to the diamond surface.
// (For a convex polyhedron defined as the intersection of half-spaces,
//  the SDF is given by the maximum (over all facets) of the plane functions.)
float diamondSDF(in vec3 p)
{
    // Start with a very low value.
    float d = -1e5;

    // ----- TABLE FACET -----
    // The top facet is horizontal (normal up)
    float table = dot(vec3(0.0,2.0,0.0), p) - T;
    d = max(d, table);

    // ----- CROWN FACETS (8 facets) -----
    // Each crown facet is defined by a triangle:
    // Two vertices on the table edge and one on the girdle (y=0).
    for (int i = 0; i < 32; i++) {
        float a0 = float(i) * (PI/16.0);
        float a1 = float(i+1) * (PI/16.0);
        float am = (a0 + a1) * 0.5;
        vec3 A = vec3(R * cos(a0), T, R * sin(a0));
        vec3 B = vec3(R * cos(a1), T, R * sin(a1));
        vec3 C = vec3(R2 * cos(am), 0.0, R2 * sin(am));
        // Compute the plane normal from the triangle (A,B,C)
        vec3 n = normalize(cross(B - A, C - A));
        float d_val = dot(n, A);
        // Ensure that inside points satisfy: dot(n,p)-d_val <= 0.
        if( dot(n, vec3(0.0)) - d_val > 0.0 ) {
            n = -n;
            d_val = -d_val;
        }
        float crown = dot(n, p) - d_val;
        d = max(d, crown);
    }

    // ----- PAVILION FACETS (8 facets) -----
    // Each pavilion facet is defined by a triangle that goes through:
    // The culet (the bottom point at (0,-P,0)) and two adjacent points on the girdle.
    for (int i = 0; i < 32; i++) {
        float a0 = (float(i)   + 0.2) * (PI/16.0);
        float a1 = (float(i+1) + 0.5) * (PI/16.0);
        vec3 A = vec3(0.0, -P/2.4, 0.0); // culet (tip)
        vec3 B = vec3(R2 * cos(a0), 0.0, R2 * sin(a0));
        vec3 C = vec3(R2 * cos(a1), 0.0, R2 * sin(a1));
        vec3 n = normalize(cross(B - A, C - A));
        float d_val = dot(n, A);
        if( dot(n, vec3(0.0)) - d_val > 0.0 ) {
            n = -n;
            d_val = -d_val;
        }
        float pav = dot(n, p) - d_val;
        d = max(d, pav);
    }

    return d;
}

// ------------------------------------------------------------------
// Estimate normal by central differences.
vec3 getNormal(in vec3 p)
{
    return normalize(vec3(
        diamondSDF(p + vec3(EPSILON,0.0,0.0)) - diamondSDF(p - vec3(EPSILON,0.0,0.0)),
        diamondSDF(p + vec3(0.0,EPSILON,0.0)) - diamondSDF(p - vec3(0.0,EPSILON,0.0)),
        diamondSDF(p + vec3(0.0,0.0,EPSILON)) - diamondSDF(p - vec3(0.0,0.0,EPSILON))
    ));
}

// ------------------------------------------------------------------
// A simple Y-axis rotation matrix.
mat3 rotationY(float angle)
{
    float c = cos(angle);
    float s = sin(angle);
    return mat3(
        c,   0.0, -s,
        0.0, 1.0,  0.0,
        s,   0.0,  c
    );
}

// ------------------------------------------------------------------
// Main render: ray march the diamond and shade it using environment mapping.
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalize screen coordinates (uv)
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // ----- CAMERA SETUP -----
    // Rotate the camera slowly around the diamond.
    float angle = iTime * 0.3;
    // Add a zoom in/out effect by modulating the camera distance over time.
    float zoomFactor = 0.5 + 0.2 * sin(iTime * 1.0); // Adjust amplitude (0.2) and speed (2.0) as desired.
    float radius = 3.0 * zoomFactor;
    vec3 ro = vec3(radius * sin(angle), 0.5, radius * cos(angle));
    vec3 target = vec3(0.0, 0.0, 0.0);
    vec3 forward = normalize(target - ro);
    vec3 right = normalize(cross(forward, vec3(angle,angle,angle)));
    vec3 up = cross(right, forward);
    // Set up a simple pinhole camera.
    float focalLength = 1.0;
    vec3 rd = normalize(uv.x * right + uv.y * up - 0.05 + focalLength * forward);

    // ----- RAY MARCHING -----
    float t = 0.0;
    float d;
    vec3 pos;
    bool hit = false;
    for (int i = 0; i < MAX_STEPS; i++) {
        pos = ro + rd * t;
        d = diamondSDF(pos);
        if(d < EPSILON) { 
            hit = true; 
            break; 
        }
        t += d;
        if(t > MAX_DIST) break;
    }

    vec3 color = vec3(0.0);

    if(hit)
    {
        // Compute hit-point and normal.
        vec3 posHit = pos;
        vec3 normal = getNormal(posHit);

        // ----- REFLECTION & DISPERSION -----
        // Compute the perfect reflection vector.
        vec3 refl = reflect(rd, normal);
        // Compute refracted vectors with slightly different indices of refraction
        // to simulate dispersion (diamond’s index is ~2.42).
        float etaR = 1.0 / 2.42;
        float etaG = 1.0 / 2.41;
        float etaB = 1.0 / 2.40;
        vec3 refrR = refract(rd, normal, etaR);
        vec3 refrG = refract(rd, normal, etaG);
        vec3 refrB = refract(rd, normal, etaB);

        // Schlick’s Fresnel approximation:
        float fresnel = pow(1.0 - max(dot(rd, normal), 0.0), 5.0);

        // ----- ENVIRONMENT MAPPING -----
        // Sample the cubemap in reflection and refraction.
        vec3 envRefl = texture(iChannel0, refl).rgb;
        vec3 envRefr;
        envRefr.r = texture(iChannel0, refrR).r;
        envRefr.g = texture(iChannel0, refrG).g;
        envRefr.b = texture(iChannel0, refrB).b;

        // Mix the two based on the Fresnel term.
        vec3 colDiamond = mix(envRefr, envRefl, fresnel);

        // A gentle rim‐light (for extra sparkle).
        float rim = smoothstep(0.0, 1.0, 1.0 - abs(dot(normal, rd)));
        colDiamond += rim * 0.1;

        color = colDiamond;
    }
    else
    {
        // No hit: show the environment cubemap.
        color = texture(iChannel0, rd).rgb;
    }

    // Gamma correction.
    color = pow(color, vec3(0.4545));

    fragColor = vec4(color, 1.0);
}
